-- Run this once on an existing st_dmv database.
ALTER TABLE dmv_locations ADD COLUMN menu_x DECIMAL(10,4) NULL, ADD COLUMN menu_y DECIMAL(10,4) NULL, ADD COLUMN menu_z DECIMAL(10,4) NULL;
ALTER TABLE dmv_locations ADD COLUMN updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE dmv_vehicle_ledger ADD COLUMN registration_expires_at DATETIME NULL;
CREATE TABLE IF NOT EXISTS dmv_settings (setting_key VARCHAR(64) NOT NULL, setting_value TEXT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(setting_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dmv_custom_plate_requests (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,citizenid VARCHAR(80) NOT NULL,vehicle_ledger_id BIGINT UNSIGNED NOT NULL,requested_plate VARCHAR(16) NOT NULL,status ENUM('PENDING','APPROVED','REJECTED','PURCHASED','CANCELLED') NOT NULL DEFAULT 'PENDING',reviewed_by VARCHAR(80) NULL,reviewed_at DATETIME NULL,rejection_reason VARCHAR(255) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_custom_plate_citizen(citizenid,status),KEY idx_custom_plate_vehicle(vehicle_ledger_id),CONSTRAINT fk_custom_plate_vehicle FOREIGN KEY(vehicle_ledger_id) REFERENCES dmv_vehicle_ledger(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO dmv_settings(setting_key,setting_value) VALUES ('registration_fee','350'),('registration_coverage_days','365'),('plate_format','OR-######'),('custom_plate_enabled','1'),('custom_plate_price','750') ON DUPLICATE KEY UPDATE setting_key=VALUES(setting_key);
